import React, { forwardRef, PropsWithChildren } from 'react';

import {
  containerTemplateFixed,
  containerTemplateResizable,
  fixedTemplateArea,
  resizableTemplateArea,
} from './chart-layout.styles.js';
import { FixedChartLayout } from './components/FixedChartLayout.js';
import { LayoutStateHandler } from './components/LayoutStateHandler.js';
import { ResizableChartLayout } from './components/ResizableChartLayout.js';
import { DEFAULT_LAYOUT_HEIGHT } from './constants.js';
import { ChartLayoutOrientationContext } from './context/ChartLayoutOrientation.context.js';
import { ChartLayoutSizeContext } from './context/ChartLayoutSize.context.js';
import { extractLayoutSlots } from './functions/extract-layout-slots.js';
import { getOrientation } from './functions/orientation.js';
import { useObserveContainerSize } from './hooks/useObserveContainerSize.js';
import { Graph } from './slots/Graph.js';
import { Legend } from './slots/Legend.js';
import type { ChartLayoutLegendProps, ChartLayoutProps } from './types.js';
import { useMergeRefs } from '../../../../core/hooks/useMergeRefs.js';
import { Grid } from '../../../../layouts-core/grid/Grid.js';
import { coerceSizeValue } from '../../functions/coerceSizeValue.js';

interface ChartLayoutContentProps {
  legendConfig?: ChartLayoutLegendProps;
  showResizer?: boolean;
  showLegend: boolean;
}
const ChartLayoutContent = ({
  children,
  legendConfig,
  showResizer = true,
  showLegend,
}: PropsWithChildren<ChartLayoutContentProps>) =>
  showResizer && showLegend ? (
    <ResizableChartLayout legendConfig={legendConfig}>
      {children}
    </ResizableChartLayout>
  ) : (
    <FixedChartLayout legendRatio={legendConfig?.ratio} showLegend={showLegend}>
      {children}
    </FixedChartLayout>
  );

export const ChartLayoutRoot = forwardRef<
  HTMLDivElement,
  PropsWithChildren<ChartLayoutProps>
>((props, forwardedRef) => {
  const {
    chartHeight,
    chartWidth = '100%',
    children,
    legendConfig,
    resizable,
    isEmpty = false,
    emptyState,
    errorState,
    showLoader = false,
    className,
    style,
  } = props;
  const legendOrientation = legendConfig?.orientation ?? 'auto';
  const [containerSizes, gridContainer] = useObserveContainerSize();
  const layoutHeight = coerceSizeValue(chartHeight) ?? DEFAULT_LAYOUT_HEIGHT;
  const containerAvailableArea = {
    width: containerSizes.width,
    height: containerSizes.height,
  };

  const mergedRefs = useMergeRefs([gridContainer, forwardedRef]);
  const orientation = getOrientation(
    containerAvailableArea.width,
    containerAvailableArea.height,
    legendOrientation,
  );

  const forceHideLegend =
    orientation === 'horizontal'
      ? containerAvailableArea.width < containerAvailableArea.height
      : containerSizes.wrapperHeight < containerAvailableArea.height;

  const { legendArea } = extractLayoutSlots(children);
  const showResizer = (resizable ?? true) && legendArea && !isEmpty;

  const templateAreas =
    showResizer && !forceHideLegend ? resizableTemplateArea : fixedTemplateArea;
  const gridTemplate =
    showResizer && !forceHideLegend
      ? containerTemplateResizable
      : containerTemplateFixed;

  const horizontalPadding =
    containerSizes.padding.left + containerSizes.padding.right;
  const width =
    typeof chartWidth === 'number'
      ? `${chartWidth - horizontalPadding}px`
      : `calc(${chartWidth} - ${horizontalPadding}px)`;

  return (
    <ChartLayoutOrientationContext.Provider value={{ orientation }}>
      <Grid
        style={{
          position: 'relative',
          overflow: 'hidden',
          ...style,
        }}
        className={className}
        width={width}
        height={layoutHeight}
        ref={mergedRefs}
        gridTemplateColumns={gridTemplate}
        gridTemplateRows={gridTemplate}
        gridTemplateAreas={templateAreas}
        gap={0}
        data-testid={'chart-layout'}
      >
        <ChartLayoutSizeContext.Provider value={containerAvailableArea}>
          <LayoutStateHandler
            empty={isEmpty}
            height={layoutHeight}
            emptyState={emptyState}
            errorState={errorState}
            showLoader={showLoader}
          >
            <ChartLayoutContent
              legendConfig={legendConfig}
              showResizer={showResizer && !forceHideLegend}
              showLegend={!legendConfig?.hidden && !forceHideLegend}
            >
              {children}
            </ChartLayoutContent>
          </LayoutStateHandler>
        </ChartLayoutSizeContext.Provider>
      </Grid>
    </ChartLayoutOrientationContext.Provider>
  );
});

ChartLayoutRoot['displayName'] = 'ChartLayout';

/**
 * Slot component for Chart Layout
 * @internal
 */
export const ChartLayout = Object.assign(ChartLayoutRoot, { Graph, Legend });
